/// runtime — as tests do — takes effect immediately.
fn truncate_len() -> Option<usize> {
    let len = std::env::var(TRUNCATE_LEN_ENV)
        .ok()
        .and_then(|v| v.trim().parse::<usize>().ok())
        .unwrap_or(DEFAULT_TRUNCATE_LEN);

    // A length of zero disables truncation.
    (len != 0).then_some(len)
}

/// Truncate a `min` statistics value.
///
/// The returned value is the longest prefix of `value` that fits within the configured byte limit.
/// For UTF-8 string columns the prefix respects Unicode character boundaries so that it remains
/// valid UTF-8; for binary columns it is truncated at the raw byte level.
pub(crate) fn truncate_min_value(value: Vec<u8>, is_utf8: bool) -> Vec<u8> {
    let Some(limit) = truncate_len() else {
        return value;
    };
    if value.len() <= limit {
        return value;
    }

    if is_utf8 {
        truncate_utf8(&value, limit).unwrap_or(value)
    } else {
        value[..limit].to_vec()
    }
}

/// Truncate a `max` statistics value.
///
/// The value is first truncated to the configured byte limit (see [`truncate_min_value`]) and then
/// incremented to produce a valid upper bound. If no valid upper bound can be produced (e.g. every
/// byte is `0xFF`) the original value is returned unchanged.
pub(crate) fn truncate_max_value(value: Vec<u8>, is_utf8: bool) -> Vec<u8> {
    let Some(limit) = truncate_len() else {
        return value;
    };
    if value.len() <= limit {
        return value;
    }

    if is_utf8 {
        truncate_utf8(&value, limit)
            .and_then(increment_utf8)
            .unwrap_or(value)
    } else {
        truncate_and_increment_binary(&value, limit).unwrap_or(value)
    }
}

/// Returns the longest valid UTF-8 prefix of `data` that fits within `length` bytes.
///
/// `data` is assumed to be valid UTF-8 (it originates from a string column). Truncation never
/// splits a multi-byte character.
fn truncate_utf8(data: &[u8], length: usize) -> Option<Vec<u8>> {
    let s = std::str::from_utf8(data).ok()?;

    // Walk the character boundaries and keep the last one that stays within the limit.
    let mut end = 0;
    for (idx, c) in s.char_indices() {
        let next = idx + c.len_utf8();
        if next > length {
            break;
        }
        end = next;
    }

    Some(data[..end].to_vec())
}

/// Increment a valid UTF-8 value to the smallest larger valid UTF-8 value that keeps the same
/// encoded length.
///
/// The last character is incremented to the next code point that encodes to the same number of
/// bytes; if that is not possible the preceding character is tried instead (and everything after
/// it dropped). Returns `None` when no character can be incremented this way.
fn increment_utf8(data: Vec<u8>) -> Option<Vec<u8>> {
    let s = std::str::from_utf8(&data).ok()?;

    for (idx, original_char) in s.char_indices().rev() {
        let original_len = original_char.len_utf8();
        if let Some(next_char) = char::from_u32(original_char as u32 + 1) {
            // Do not allow the incremented character to grow in encoded byte length, as that would
            // both change the length of the bound and could overrun the truncation limit.
            if next_char.len_utf8() == original_len {
                let mut result = data[..idx + original_len].to_vec();
                next_char.encode_utf8(&mut result[idx..]);
                return Some(result);
            }
        }
    }

    None
}

/// Produce a truncated upper bound for a binary value.
///
/// The value is truncated to at most `length` bytes and the rightmost byte that is not `0xFF` is
/// incremented (any trailing bytes are dropped). If every byte within the limit is `0xFF`, the
/// search continues beyond the limit for the first byte that can be incremented. Returns `None`
/// when every byte is `0xFF`.
fn truncate_and_increment_binary(data: &[u8], length: usize) -> Option<Vec<u8>> {
    let limit = length.min(data.len());

    // Prefer the rightmost incrementable byte within the limit.
    for i in (0..limit).rev() {
        if data[i] != u8::MAX {
            let mut result = data[..=i].to_vec();
            result[i] += 1;
            return Some(result);
        }
    }

    // Every byte within the limit is 0xFF; search beyond it for the first incrementable byte.
    for i in limit..data.len() {
        if data[i] != u8::MAX {
            let mut result = data[..=i].to_vec();
            result[i] += 1;
            return Some(result);
        }
    }

    // The value consists entirely of 0xFF bytes: no valid upper bound exists.
    None
}
